# ── data models ────────────────────────────────────────────────────────────────

class SourceType(Enum):
    EMPTY  = "empty"
    SCREEN = "screen"
    WINDOW = "window"
    TAB    = "tab"
    IMAGE  = "image"
    VIDEO  = "video"

_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".bmp", ".webp", ".gif"}
_VIDEO_EXTS = {".mp4", ".mkv", ".avi", ".mov", ".wmv", ".flv", ".m4v", ".webm"}

@dataclass
class WinInfo:
    id: str
    title: str
    app: str = ""
    bounds: Optional[tuple] = None

    def label(self) -> str:
        return f"{self.app}: {self.title}" if self.app else self.title

@dataclass
class ScreenInfo:
    index: int
    name: str
    bounds: tuple
    primary: bool = False

@dataclass
class PadConfig:
    index: int
    label: str = ""
    stype: SourceType = SourceType.EMPTY
    sid:   Optional[str] = None
    sname: str = "Empty"
    projected: bool = False
    loop: bool = True
    target_screen: Optional[int] = None  # None=Global, -1=All External, >=0=screen index

    @property
    def display_name(self) -> str:
        if self.label:
            return self.label
        return f"Pad {self.index + 1}" if self.stype == SourceType.EMPTY else self.sname


def populate_target_screen_combo(cb: QComboBox, screens: List[ScreenInfo],
                                 current_target: Optional[int]):
    """Fill a QComboBox with Global Default, individual external screens, and All External."""
    cb.clear()
    cb.addItem("Default (Global Output)", None)
    ext = [s for s in screens if not s.primary]
    for s in ext:
        cb.addItem(
            f"Display {s.index + 1}: {s.name} ({s.bounds[2]}×{s.bounds[3]})",
            s.index)
    if len(ext) > 1:
        cb.addItem(f"All External ({len(ext)} monitors)", -1)
    if current_target is not None:
        idx = cb.findData(current_target)
        if idx >= 0:
            cb.setCurrentIndex(idx)

# ── system bridge ──────────────────────────────────────────────────────────────

class Bridge:
    @staticmethod
    def screens() -> List[ScreenInfo]:
        result  = []
        primary = QApplication.primaryScreen()
        for i, s in enumerate(QApplication.screens()):
            g = s.geometry()
            result.append(ScreenInfo(
                index=i, name=s.name() or f"Display {i+1}",
                bounds=(g.x(), g.y(), g.width(), g.height()),
                primary=(s is primary),
            ))
        return result

    @staticmethod
    def external_screen() -> Optional[ScreenInfo]:
        ss  = Bridge.screens()
        ext = [s for s in ss if not s.primary]
        return ext[0] if ext else None

    @staticmethod
    def external_screens() -> List[ScreenInfo]:
        return [s for s in Bridge.screens() if not s.primary]

    @staticmethod
    def windows() -> List[WinInfo]:
        if PLATFORM == "Windows" and HAS_WIN32:
            return Bridge._wins_win32()
        if PLATFORM == "Darwin":
            return Bridge._wins_macos()
        if PLATFORM == "Linux":
            return Bridge._wins_linux()
        return []

    @staticmethod
    def _wins_win32() -> List[WinInfo]:
        wins = []
        def cb(hwnd, _):
            if not (win32gui.IsWindowVisible(hwnd) and win32gui.GetWindowText(hwnd)):
                return True
            title = win32gui.GetWindowText(hwnd)
            if len(title) < 2:
                return True
            try:
                _, pid = win32process.GetWindowThreadProcessId(hwnd)
                h   = win32api.OpenProcess(0x400, False, pid)
                app = os.path.basename(
                    win32process.GetModuleFileNameEx(h, 0)).replace(".exe", "")
                win32api.CloseHandle(h)
            except Exception:
                app = ""
            r = win32gui.GetWindowRect(hwnd)
            w, h = r[2] - r[0], r[3] - r[1]
            if w > 50 and h > 50:
                wins.append(WinInfo(str(hwnd), title, app, (r[0], r[1], w, h)))
            return True
        win32gui.EnumWindows(cb, None)
        return wins

    @staticmethod
    def _wins_macos() -> List[WinInfo]:
        wins = []
        try:
            from Quartz import (CGWindowListCopyWindowInfo,
                                kCGWindowListOptionOnScreenOnly, kCGNullWindowID)
            for w in CGWindowListCopyWindowInfo(
                    kCGWindowListOptionOnScreenOnly, kCGNullWindowID):
                name  = w.get("kCGWindowName", "")
                owner = w.get("kCGWindowOwnerName", "")
                b     = w.get("kCGWindowBounds", {})
                if not name:
                    continue
                x, y = int(b.get("X", 0)), int(b.get("Y", 0))
                ww, hh = int(b.get("Width", 0)), int(b.get("Height", 0))
                if ww > 50 and hh > 50:
                    wins.append(WinInfo(str(w.get("kCGWindowNumber", "")),
                                        name, owner, (x, y, ww, hh)))
        except Exception:
            pass
        return wins

    @staticmethod
    def _wins_linux() -> List[WinInfo]:
        wins = []
        try:
            out = subprocess.check_output(["wmctrl", "-l", "-G"],
                                          text=True, timeout=3)
            for line in out.splitlines():
                parts = line.split(None, 7)
                if len(parts) < 8:
                    continue
                wid   = parts[0]
                x, y  = int(parts[2]), int(parts[3])
                w, h  = int(parts[4]), int(parts[5])
                title = parts[7]
                if title and w > 50 and h > 50 and title not in ("N/A", ""):
                    wins.append(WinInfo(wid, title, bounds=(x, y, w, h)))
        except Exception:
            try:
                out = subprocess.check_output(
                    ["xdotool", "search", "--onlyvisible", "--name", ""],
                    text=True, timeout=3)
                for wid in out.splitlines():
                    if not wid:
                        continue
                    try:
                        name = subprocess.check_output(
                            ["xdotool", "getwindowname", wid],
                            text=True, timeout=1).strip()
                        if name:
                            wins.append(WinInfo(wid, name))
                    except Exception:
                        pass
            except Exception:
                pass
        return wins

    @staticmethod
    def _iter_tab_items(hwnd: int):
        """Yield TabItemControl nodes for a browser window, skipping web DocumentControls."""
        ctrl = auto.ControlFromHandle(hwnd)
        if not ctrl:
            return
        queue = [(ctrl, 0)]
        while queue:
            node, depth = queue.pop(0)
            if depth > 16:
                continue
            ct = node.ControlType
            if ct == auto.ControlType.DocumentControl:
                continue
            if ct == auto.ControlType.TabItemControl:
                yield node
                continue
            try:
                for ch in node.GetChildren():
                    queue.append((ch, depth + 1))
            except Exception:
                pass

    @staticmethod
    def browser_tabs() -> List[tuple]:
        """Return list of (hwnd_str, tab_title, app_name) for open browser tabs."""
        if PLATFORM != "Windows" or not (HAS_WIN32 and HAS_UIA):
            return []
        browser_apps = ("chrome", "msedge", "brave", "opera", "vivaldi", "firefox")
        tabs: List[tuple] = []
        wins = Bridge._wins_win32()
        for w in wins:
            if w.app.lower().replace(".exe", "") not in browser_apps:
                continue
            try:
                hwnd = int(w.id)
                with auto.UIAutomationInitializerInThread():
                    seen = set()
                    for node in Bridge._iter_tab_items(hwnd):
                        name = (node.Name or "").strip()
                        if name and name not in seen:
                            seen.add(name)
                            tabs.append((w.id, name, w.app))
            except Exception:
                pass
        return tabs

    @staticmethod
    def activate_browser_tab(hwnd_str: str, tab_title: str) -> bool:
        """Switch a browser window to the specified tab via UI Automation."""
        if PLATFORM != "Windows" or not (HAS_WIN32 and HAS_UIA):
            return False
        try:
            hwnd = int(hwnd_str)
            with auto.UIAutomationInitializerInThread():
                for node in Bridge._iter_tab_items(hwnd):
                    name = (node.Name or "").strip()
                    if name == tab_title or tab_title in name:
                        try:
                            pat = node.GetSelectionItemPattern()
                            if pat:
                                pat.Select()
                                return True
                        except Exception:
                            pass
                        try:
                            pat = node.GetInvokePattern()
                            if pat:
                                pat.Invoke()
                                return True
                        except Exception:
                            pass
        except Exception:
            pass
        return False

    @staticmethod
    def ensure_extend_mode():
        """Switch Windows display mode to Extend so all connected monitors turn on."""
        if PLATFORM != "Windows":
            return
        try:
            subprocess.Popen(
                ["DisplaySwitch.exe", "/extend"],
                creationflags=0x08000000,
            )
        except Exception:
            pass

    @staticmethod
    def move_windows_to_primary(exclude_hwnds: Optional[set] = None):
        """Move visible app windows from secondary monitors onto the primary monitor."""
        if PLATFORM != "Windows" or not HAS_WIN32:
            return
        primary = QApplication.primaryScreen()
        if not primary:
            return
        pg = primary.availableGeometry()
        px, py, pw, ph = pg.x(), pg.y(), pg.width(), pg.height()
        skip_classes = {
            "Shell_TrayWnd", "Shell_SecondaryTrayWnd",
            "Progman", "WorkerW", "Windows.UI.Core.CoreWindow",
        }
        excl = exclude_hwnds or set()

        def cb(hwnd, _):
            if hwnd in excl:
                return True
            if not win32gui.IsWindowVisible(hwnd):
                return True
            if ctypes.windll.user32.IsIconic(hwnd):
                return True
            if not win32gui.GetWindowText(hwnd):
                return True
            try:
                cls = win32gui.GetClassName(hwnd)
                if cls in skip_classes:
                    return True
                cloaked = ctypes.c_int(0)
                ctypes.windll.dwmapi.DwmGetWindowAttribute(
                    hwnd, 14, ctypes.byref(cloaked), ctypes.sizeof(cloaked))
                if cloaked.value != 0:
                    return True
            except Exception:
                pass
            try:
                r = win32gui.GetWindowRect(hwnd)
                w, h = r[2] - r[0], r[3] - r[1]
                if w <= 50 or h <= 50 or r[0] <= -30000:
                    return True
                cx, cy = r[0] + w // 2, r[1] + h // 2
                # Already on primary monitor
                if px <= cx < px + pw and py <= cy < py + ph:
                    return True
                placement = win32gui.GetWindowPlacement(hwnd)
                was_max = (placement[1] == win32con.SW_SHOWMAXIMIZED)
                if was_max:
                    win32gui.ShowWindow(hwnd, win32con.SW_RESTORE)
                nw = min(w, pw - 40)
                nh = min(h, ph - 40)
                nx = px + max(0, (pw - nw) // 2)
                ny = py + max(0, (ph - nh) // 2)
                win32gui.SetWindowPos(
                    hwnd, 0, nx, ny, nw, nh,
                    win32con.SWP_NOZORDER | win32con.SWP_NOACTIVATE)
                if was_max:
                    win32gui.ShowWindow(hwnd, win32con.SW_MAXIMIZE)
            except Exception:
                pass
            return True

        try:
            win32gui.EnumWindows(cb, None)
        except Exception:
            pass

    @staticmethod
    def cameras(max_probe: int = 6) -> List[int]:
        """Probe available physical camera indices via OpenCV."""
        if not HAS_CV2:
            return []
        found = []
        backend = cv2.CAP_DSHOW if PLATFORM == "Windows" else cv2.CAP_ANY
        for i in range(max_probe):
            cap = cv2.VideoCapture(i, backend)
            if not cap.isOpened() and backend != cv2.CAP_ANY:
                cap.release()
                cap = cv2.VideoCapture(i)
            if cap.isOpened():
                found.append(i)
            cap.release()
        return found


def compose_pip_frame(main_px: QPixmap, target_size: QSize,
                      pip_px: Optional[QPixmap] = None,
                      size_pct: int = 25, margin: int = 24,
                      rounded: bool = True) -> QPixmap:
    """Render main_px centered into target_size with optional lower-right PIP."""
    w = max(1, target_size.width())
    h = max(1, target_size.height())
    canvas = QPixmap(w, h)
    canvas.fill(Qt.black)
    p = QPainter(canvas)
    p.setRenderHint(QPainter.SmoothPixmapTransform, True)
    p.setRenderHint(QPainter.Antialiasing, True)

    if main_px and not main_px.isNull():
        sc = main_px.scaled(w, h, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        ox = (w - sc.width()) // 2
        oy = (h - sc.height()) // 2
        p.drawPixmap(ox, oy, sc)

    if pip_px and not pip_px.isNull():
        pip_w = max(80, int(w * max(10, min(50, size_pct)) / 100.0))
        pip_sc = pip_px.scaledToWidth(pip_w, Qt.SmoothTransformation)
        # Clamp height if needed
        max_h = int(h * 0.45)
        if pip_sc.height() > max_h:
            pip_sc = pip_px.scaledToHeight(max_h, Qt.SmoothTransformation)
        pw, ph = pip_sc.width(), pip_sc.height()
        m = max(4, int(margin * (w / 1920.0))) if w < 1280 else margin
        px = max(0, w - pw - m)
        py = max(0, h - ph - m)
        if rounded:
            radius = max(6, min(16, pw // 20))
            path = QPainterPath()
            path.addRoundedRect(px, py, pw, ph, radius, radius)
            p.save()
            p.setClipPath(path)
            p.drawPixmap(px, py, pip_sc)
            p.restore()
            p.setPen(QColor(255, 255, 255, 170))
            p.drawRoundedRect(px, py, pw, ph, radius, radius)
        else:
            p.drawPixmap(px, py, pip_sc)
            p.setPen(QColor(255, 255, 255, 140))
            p.drawRect(px, py, pw, ph)

    p.end()
    return canvas

# ── capture engine ─────────────────────────────────────────────────────────────

class Capture:
    _lock = threading.Lock()

    @classmethod
    def grab(cls, x: int, y: int, w: int, h: int) -> Optional[QPixmap]:
        if w <= 0 or h <= 0:
            return None
        try:
            with cls._lock:
                with mss.mss() as sct:
                    img = sct.grab({"top": y, "left": x, "width": w, "height": h})
                    qi = QImage(bytes(img.bgra), img.width, img.height,
                                img.width * 4, QImage.Format_ARGB32)
                    return QPixmap.fromImage(qi)
        except Exception:
            return None

    @staticmethod
    def _is_window_minimized_win32(hwnd: int) -> bool:
        try:
            if not win32gui.IsWindow(hwnd) or not win32gui.IsWindowVisible(hwnd):
                return True
            if ctypes.windll.user32.IsIconic(hwnd):
                return True
            placement = win32gui.GetWindowPlacement(hwnd)
            if placement[1] == win32con.SW_SHOWMINIMIZED:
                return True
            # Check DWM cloaked state (e.g. UWP / virtual desktop hidden windows)
            try:
                cloaked = ctypes.c_int(0)
                ctypes.windll.dwmapi.DwmGetWindowAttribute(
                    hwnd, 14, ctypes.byref(cloaked), ctypes.sizeof(cloaked))
                if cloaked.value != 0:
                    return True
            except Exception:
                pass
            rect = win32gui.GetWindowRect(hwnd)
            w = rect[2] - rect[0]
            h = rect[3] - rect[1]
            if rect[0] <= -30000 or rect[1] <= -30000 or w < 80 or h < 80:
                return True
        except Exception:
            return False
        return False

    @staticmethod
    def _is_blank_image(qi: QImage) -> bool:
        """Return True if an 8x8 sample grid across qi is all pure black."""
        w, h = qi.width(), qi.height()
        if w <= 0 or h <= 0:
            return True
        for iy in range(1, 9):
            y = (h * iy) // 9
            for ix in range(1, 9):
                x = (w * ix) // 9
                px = qi.pixel(x, y)
                if (px & 0x00FFFFFF) != 0:
                    return False
        return True

    @classmethod
    def grab_window_win32(cls, hwnd_str: str) -> Optional[QPixmap]:
        if not HAS_WIN32:
            return None
        try:
            hwnd = int(hwnd_str)
            if cls._is_window_minimized_win32(hwnd):
                return None
            rect = win32gui.GetWindowRect(hwnd)
            w = rect[2] - rect[0]
            h = rect[3] - rect[1]
            if w <= 0 or h <= 0:
                return None
            hwnd_dc  = win32gui.GetWindowDC(hwnd)
            mfc_dc   = win32ui.CreateDCFromHandle(hwnd_dc)
            mem_dc   = mfc_dc.CreateCompatibleDC()
            bmp      = win32ui.CreateBitmap()
            bmp.CreateCompatibleBitmap(mfc_dc, w, h)
            mem_dc.SelectObject(bmp)
            ok = ctypes.windll.user32.PrintWindow(hwnd, mem_dc.GetSafeHdc(), 2)
            if not ok:
                ok = ctypes.windll.user32.PrintWindow(hwnd, mem_dc.GetSafeHdc(), 0)
            info = bmp.GetInfo()
            data = bmp.GetBitmapBits(True)
            win32gui.DeleteObject(bmp.GetHandle())
            mem_dc.DeleteDC()
            mfc_dc.DeleteDC()
            win32gui.ReleaseDC(hwnd, hwnd_dc)
            if not ok:
                return None
            qi = QImage(data, info['bmWidth'], info['bmHeight'], QImage.Format_ARGB32)
            # Re-check minimize state after PrintWindow (catches race during animation)
            if cls._is_window_minimized_win32(hwnd) or cls._is_blank_image(qi):
                return None
            return QPixmap.fromImage(qi)
        except Exception:
            return None

    @classmethod
    def for_pad(cls, cfg: PadConfig, screens: List[ScreenInfo],
                windows: List[WinInfo]) -> Optional[QPixmap]:
        if cfg.stype == SourceType.SCREEN:
            try:
                s = next(s for s in screens if str(s.index) == cfg.sid)
                return cls.grab(*s.bounds)
            except StopIteration:
                return None
        if cfg.stype == SourceType.WINDOW:
            try:
                win = next(w for w in windows if w.id == cfg.sid)
            except StopIteration:
                return None
            if PLATFORM == "Windows" and HAS_WIN32:
                return cls.grab_window_win32(win.id)
            if win.bounds:
                return cls.grab(*win.bounds)
        if cfg.stype == SourceType.TAB and cfg.sid and "|" in cfg.sid:
            hwnd_str, tab_title = cfg.sid.split("|", 1)
            if PLATFORM == "Windows" and HAS_WIN32:
                try:
                    hwnd = int(hwnd_str)
                    if not win32gui.IsWindow(hwnd):
                        return None
                    win_title = win32gui.GetWindowText(hwnd) or ""
                    # Freeze on last frame when user switches to another tab
                    if tab_title not in win_title:
                        return None
                except Exception:
                    return None
                return cls.grab_window_win32(hwnd_str)
        return None

# ── capture worker thread ──────────────────────────────────────────────────────

class CaptureThread(QThread):
    frame = pyqtSignal(int, QPixmap)

    def __init__(self, pads: List[PadConfig]):
        super().__init__()
        self.pads    = pads
        self._screens: List[ScreenInfo] = []
        self._windows: List[WinInfo]    = []
        self._fps    = DEFAULT_FPS
        self._live   = False
        self._mu     = threading.Lock()

    def set_sources(self, screens: List[ScreenInfo], windows: List[WinInfo]):
        with self._mu:
            self._screens = screens[:]
            self._windows = windows[:]

    def set_fps(self, v: int):
        self._fps = max(1, min(v, 10))

    def stop(self):
        self._live = False

    def run(self):
        self._live = True
        while self._live:
            t0 = time.time()
            with self._mu:
                ss, ws, cfgs = self._screens[:], self._windows[:], self.pads[:]
            for cfg in cfgs:
                if not self._live:
                    break
                if cfg.stype in (SourceType.EMPTY, SourceType.IMAGE, SourceType.VIDEO):
                    continue
                # Special pads handle their own previews
                if cfg.index in (CAMERA_PIP_PAD, QUAD_PAD, WEBCAM_PAD_VIDEO):
                    continue
                px = Capture.for_pad(cfg, ss, ws)
                if px:
                    self.frame.emit(cfg.index, px)
            dt = time.time() - t0
            time.sleep(max(0.0, 1.0 / self._fps - dt))

# ── projector capture thread ───────────────────────────────────────────────────

class ProjectorThread(QThread):
    frame = pyqtSignal(QPixmap)
    error = pyqtSignal(str)

    def __init__(self):
        super().__init__()
        self._cfg: Optional[PadConfig]   = None
        self._quad_pads: List[PadConfig] = []
        self._quad_mode: bool            = False
        self._screens: List[ScreenInfo]  = []
        self._windows: List[WinInfo]     = []
        self._fps    = 60
        self._live   = False
        self._mu     = threading.Lock()
        self._last_frame: Optional[QPixmap] = None  # freeze-on-minimise cache
        self._img_path: str = ""
        self._img_px: Optional[QPixmap] = None
        self._vid_path: str = ""
        self._vid_cap = None
        self._vid_fps: float = 25.0
        self._audio_proc = None

    def set_target(self, cfg: PadConfig, screens: List[ScreenInfo],
                   windows: List[WinInfo]):
        with self._mu:
            self._cfg        = cfg
            self._quad_mode  = False
            self._screens    = screens[:]
            self._windows    = windows[:]
            self._last_frame = None

    def set_quad_mode(self, pads: List["PadConfig"], screens: List[ScreenInfo],
                      windows: List[WinInfo]):
        with self._mu:
            self._quad_pads  = pads[:4]
            self._quad_mode  = True
            self._cfg        = None
            self._screens    = screens[:]
            self._windows    = windows[:]
            self._last_frame = None

    def update_sources(self, screens: List[ScreenInfo], windows: List[WinInfo]):
        with self._mu:
            self._screens = screens[:]
            self._windows = windows[:]

    def set_fps(self, fps: int):
        self._fps = max(1, min(fps, 120))

    def stop(self):
        self._live = False

    def _release_video(self):
        if self._vid_cap is not None:
            try:
                self._vid_cap.release()
            except Exception:
                pass
            self._vid_cap = None
        self._vid_path = ""
        if self._audio_proc is not None:
            try:
                self._audio_proc.terminate()
            except Exception:
                pass
            self._audio_proc = None

    def _start_audio(self, path: str):
        try:
            flags = 0x08000000 if PLATFORM == "Windows" else 0
            self._audio_proc = subprocess.Popen(
                ["ffplay", "-nodisp", "-autoexit", "-vn", path],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=flags,
            )
        except (FileNotFoundError, OSError):
            self._audio_proc = None

    def run(self):
        self._live = True
        try:
            while self._live:
                t0 = time.time()
                with self._mu:
                    quad, cfg, pads = self._quad_mode, self._cfg, self._quad_pads[:]
                    ss, ws = self._screens[:], self._windows[:]

                target_fps = self._fps

                if quad:
                    self._release_video()
                    composite = self._compose_quad(pads, ss, ws)
                    if composite:
                        self._last_frame = composite
                        self.frame.emit(composite)
                    elif self._last_frame:
                        self.frame.emit(self._last_frame)

                elif cfg and cfg.stype == SourceType.IMAGE:
                    self._release_video()
                    path = cfg.sid or ""
                    if path != self._img_path:
                        self._img_path = path
                        px = QPixmap(path)
                        self._img_px = px if not px.isNull() else None
                    if self._img_px:
                        self.frame.emit(self._img_px)
                    target_fps = min(self._fps, 15)

                elif cfg and cfg.stype == SourceType.VIDEO:
                    path = cfg.sid or ""
                    if path != self._vid_path:
                        self._release_video()
                        self._vid_path = path
                        if not HAS_CV2:
                            self.error.emit("opencv-python is required for video playback.")
                            self._live = False
                            break
                        cap = cv2.VideoCapture(path)
                        if not cap.isOpened():
                            cap.release()
                            self.error.emit(f"Could not open video file:\n{path}")
                            self._live = False
                            break
                        self._vid_cap = cap
                        self._vid_fps = cap.get(cv2.CAP_PROP_FPS) or 25.0
                        if self._vid_fps <= 1 or self._vid_fps > 120:
                            self._vid_fps = 25.0
                        self._start_audio(path)

                    if self._vid_cap is not None:
                        ret, frame = self._vid_cap.read()
                        if not ret:
                            if cfg.loop:
                                self._vid_cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                                ret, frame = self._vid_cap.read()
                                if self._audio_proc is not None:
                                    try:
                                        self._audio_proc.terminate()
                                    except Exception:
                                        pass
                                    self._audio_proc = None
                                    self._start_audio(path)
                        if ret and frame is not None:
                            rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                            h, w, _ = rgb.shape
                            qi = QImage(rgb.tobytes(), w, h, w * 3, QImage.Format_RGB888)
                            px = QPixmap.fromImage(qi)
                            self._last_frame = px
                            self.frame.emit(px)
                        elif self._last_frame:
                            self.frame.emit(self._last_frame)
                        target_fps = self._vid_fps

                elif cfg and cfg.stype != SourceType.EMPTY:
                    self._release_video()
                    px = Capture.for_pad(cfg, ss, ws)
                    if px:
                        self._last_frame = px
                        self.frame.emit(px)
                    elif self._last_frame:
                        self.frame.emit(self._last_frame)  # freeze on minimised window
                else:
                    self._release_video()

                dt = time.time() - t0
                time.sleep(max(0.0, 1.0 / max(1.0, target_fps) - dt))
        finally:
            self._release_video()

    @staticmethod
    def _compose_quad(pads: List["PadConfig"], ss: list, ws: list) -> Optional[QPixmap]:
        W, H = 1920, 1080
        hw, hh = W // 2, H // 2
        result = QImage(W, H, QImage.Format_ARGB32)
        result.fill(Qt.black)
        painter = QPainter(result)
        positions = [(0, 0), (hw, 0), (0, hh), (hw, hh)]
        any_frame = False
        for pad, (ox, oy) in zip(pads, positions):
            if pad.stype == SourceType.EMPTY:
                continue
            px = Capture.for_pad(pad, ss, ws)
            if not px:
                continue
            any_frame = True
            scaled = px.scaled(hw - 4, hh - 4,
                               Qt.KeepAspectRatio, Qt.SmoothTransformation)
            x = ox + (hw - scaled.width()) // 2
            y = oy + (hh - scaled.height()) // 2
            painter.drawPixmap(x, y, scaled)
            # Pad number badge
            painter.setPen(QColor(C_QUAD))
            painter.setFont(QFont("Segoe UI,Inter,sans-serif", 11, QFont.Bold))
            painter.drawText(ox + 8, oy + hh - 8, f"Pad {pad.index + 1}")
        # Divider lines
        painter.setPen(QColor("#333333"))
        painter.drawLine(hw, 0, hw, H)
        painter.drawLine(0, hh, W, hh)
        painter.end()
        return QPixmap.fromImage(result) if any_frame else None

# ── camera PIP capture thread ─────────────────────────────────────────────────

class CameraPipThread(QThread):
    """Captures physical webcam/camera feed for Pad 6 lower-right PIP overlay."""
    frame   = pyqtSignal(QPixmap)
    error   = pyqtSignal(str)
    stopped = pyqtSignal()

    def __init__(self, cam_index: int = 0, width: int = 1280, height: int = 720,
                 mirror: bool = False):
        super().__init__()
        self._cam_index = cam_index
        self._width     = width
        self._height    = height
        self._mirror    = mirror
        self._live      = False

    def stop(self):
        self._live = False

    def run(self):
        if not HAS_CV2:
            self.error.emit(
                "opencv-python is required for camera input.\n\n"
                "Install:  pip install opencv-python")
            self.stopped.emit()
            return
        backend = cv2.CAP_DSHOW if PLATFORM == "Windows" else cv2.CAP_ANY
        cap = cv2.VideoCapture(self._cam_index, backend)
        if not cap.isOpened() and backend != cv2.CAP_ANY:
            cap.release()
            cap = cv2.VideoCapture(self._cam_index)
        if not cap.isOpened():
            cap.release()
            self.error.emit(
                f"Could not open Camera {self._cam_index}.\n\n"
                "Check that the camera is connected and not in use by another app.")
            self.stopped.emit()
            return
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, self._width)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, self._height)
        self._live = True
        try:
            while self._live:
                t0 = time.time()
                ret, frame = cap.read()
                if ret and frame is not None:
                    if self._mirror:
                        frame = cv2.flip(frame, 1)
                    rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                    h, w, _ = rgb.shape
                    qi = QImage(rgb.tobytes(), w, h, w * 3, QImage.Format_RGB888)
                    self.frame.emit(QPixmap.fromImage(qi))
                dt = time.time() - t0
                time.sleep(max(0.005, 1.0 / 30 - dt))
        finally:
            cap.release()
            self.stopped.emit()

# ── webcam output thread ───────────────────────────────────────────────────────

class WebcamThread(QThread):
    """Outputs a video file or screen/window as a virtual webcam via pyvirtualcam."""
    frame_preview = pyqtSignal(int, QPixmap)
    error         = pyqtSignal(str)
    stopped       = pyqtSignal()

    def __init__(self):
        super().__init__()
        self._live        = False
        self._mu          = threading.Lock()
        self._video_path: str = ""
        self._screen_cfg: Optional[PadConfig] = None
        self._screens:    list = []
        self._windows:    list = []

    def set_video_mode(self, path: str):
        with self._mu:
            self._video_path = path
            self._screen_cfg = None

    def set_screen_mode(self, cfg: "PadConfig", screens, windows):
        with self._mu:
            self._screen_cfg = cfg
            self._screens    = list(screens)
            self._windows    = list(windows)
            self._video_path = ""

    def stop(self):
        self._live = False

    def run(self):
        self._live = True
        with self._mu:
            is_screen = self._screen_cfg is not None
        if is_screen:
            self._run_screen()
        else:
            self._run_video()
        self.stopped.emit()

    def _run_video(self):
        if not HAS_PYVIRTUALCAM:
            self.error.emit(
                "pyvirtualcam not installed.\n\n"
                "Install:  pip install pyvirtualcam\n\n"
                "Also requires OBS Studio with OBS Virtual Camera enabled.")
            return
        if not HAS_CV2:
            self.error.emit(
                "opencv-python not installed.\n\n"
                "Install:  pip install opencv-python")
            return
        with self._mu:
            path = self._video_path
        cap = cv2.VideoCapture(path)
        if not cap.isOpened():
            cap.release()
            self.error.emit(f"Could not open video file:\n{path}")
            return
        fps   = cap.get(cv2.CAP_PROP_FPS) or 25.0
        iw    = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        ih    = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        cam_w = max((iw // 2) * 2, 640)
        cam_h = max((ih // 2) * 2, 480)
        audio_proc = None
        try:
            flags = 0x08000000 if PLATFORM == "Windows" else 0
            audio_proc = subprocess.Popen(
                ["ffplay", "-nodisp", "-autoexit", "-vn", path],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                creationflags=flags,
            )
        except (FileNotFoundError, OSError):
            pass
        _backend = AppConfig.get("webcam_driver", "")
        _cam_kw2: dict = dict(width=cam_w, height=cam_h, fps=int(fps),
                              fmt=pyvirtualcam.PixelFormat.RGB, print_fps=False)
        if _backend == "unity":
            _cam_kw2["backend"] = "unitycapture"
        try:
            with pyvirtualcam.Camera(**_cam_kw2) as cam:
                frame_num    = 0
                prev_interval = max(1, int(fps // 5))
                while self._live:
                    ret, frame = cap.read()
                    if not ret:
                        break
                    frame_rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                    if frame_rgb.shape[1] != cam_w or frame_rgb.shape[0] != cam_h:
                        frame_rgb = cv2.resize(frame_rgb, (cam_w, cam_h))
                    cam.send(frame_rgb)
                    cam.sleep_until_next_frame()
                    frame_num += 1
                    if frame_num % prev_interval == 0:
                        qi = QImage(frame_rgb.tobytes(), cam_w, cam_h,
                                    cam_w * 3, QImage.Format_RGB888)
                        self.frame_preview.emit(WEBCAM_PAD_VIDEO,
                                                QPixmap.fromImage(qi))
        except Exception as ex:
            self.error.emit(f"Video webcam error:\n{ex}")
        finally:
            cap.release()
            if audio_proc:
                try:
                    audio_proc.terminate()
                except Exception:
                    pass

    def _run_screen(self):
        if not HAS_PYVIRTUALCAM:
            self.error.emit(
                "pyvirtualcam not installed.\n\n"
                "Install:  pip install pyvirtualcam\n\n"
                "Also requires OBS Studio with OBS Virtual Camera enabled.")
            return
        if not HAS_CV2:
            self.error.emit(
                "opencv-python not installed.\n\n"
                "Install:  pip install opencv-python")
            return
        with self._mu:
            cfg     = self._screen_cfg
            screens = self._screens[:]
            windows = self._windows[:]
        cam_w, cam_h = 1280, 720
        fps = 30
        _backend = AppConfig.get("webcam_driver", "")
        _cam_kw = dict(width=cam_w, height=cam_h, fps=fps,
                       fmt=pyvirtualcam.PixelFormat.RGB, print_fps=False)
        if _backend == "unity":
            _cam_kw["backend"] = "unitycapture"
        prev_interval = max(1, fps // 5)
        frame_num = 0
        try:
            import numpy as _np
            with pyvirtualcam.Camera(**_cam_kw) as cam:
                while self._live:
                    px = Capture.for_pad(cfg, screens, windows)
                    if px:
                        qi = px.toImage().convertToFormat(QImage.Format_RGB888)
                        bw, bh = qi.width(), qi.height()
                        ptr = qi.bits()
                        ptr.setsize(bh * bw * 3)
                        frame_rgb = _np.frombuffer(ptr, _np.uint8).reshape(
                            (bh, bw, 3)).copy()
                        if frame_rgb.shape[1] != cam_w or frame_rgb.shape[0] != cam_h:
                            frame_rgb = cv2.resize(frame_rgb, (cam_w, cam_h))
                        cam.send(frame_rgb)
                        frame_num += 1
                        if frame_num % prev_interval == 0:
                            qi2 = QImage(frame_rgb.tobytes(), cam_w, cam_h,
                                         cam_w * 3, QImage.Format_RGB888)
                            self.frame_preview.emit(WEBCAM_PAD_VIDEO,
                                                    QPixmap.fromImage(qi2))
                    cam.sleep_until_next_frame()
        except Exception as ex:
            self.error.emit(f"Screen webcam error:\n{ex}")

# ── pad widget ─────────────────────────────────────────────────────────────────

class PadWidget(QFrame):
    clicked        = pyqtSignal(int)
    configure      = pyqtSignal(int)
    target_changed = pyqtSignal(int, object)

    def __init__(self, cfg: PadConfig):
        super().__init__()
        self.cfg          = cfg
        self._screens: List[ScreenInfo] = []
        self._projected   = False
        self._selected    = False
        self._webcam_live = False
        self._setup()

    def set_screens(self, screens: List[ScreenInfo]):
        self._screens = screens[:]

    def _setup(self):
        from PyQt5.QtWidgets import QSizePolicy
        self.setMinimumSize(170, 128)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        self.setObjectName("Pad")
        self.setCursor(Qt.PointingHandCursor)

        vl = QVBoxLayout(self)
        vl.setContentsMargins(0, 0, 0, 0)
        vl.setSpacing(0)

        self.preview = QLabel()
        self.preview.setAlignment(Qt.AlignCenter)
        self.preview.setObjectName("Preview")
        self.preview.setMinimumHeight(96)
        self.preview.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Ignored)
        self._placeholder()

        footer = QWidget()
        footer.setObjectName("Footer")
        footer.setFixedHeight(28)
        fl = QHBoxLayout(footer)
        fl.setContentsMargins(8, 0, 6, 0)
        fl.setSpacing(4)

        self.dot = QLabel("●")
        self.dot.setObjectName("Dot")
        self.dot.setFixedWidth(10)

        self.name = QLabel(self._default_footer_name())
        self.name.setObjectName("Name")

        self.sc_lbl = QLabel(f"Ctrl+{self.cfg.index + 1}")
        self.sc_lbl.setObjectName("ShortcutLbl")
        self.sc_lbl.setFixedWidth(44)
        self.sc_lbl.setAlignment(Qt.AlignRight | Qt.AlignVCenter)

        self.btn = QToolButton()
        self.btn.setText("⚙")
        self.btn.setObjectName("Gear")
        self.btn.setFixedSize(18, 18)
        self.btn.clicked.connect(lambda: self.configure.emit(self.cfg.index))

        fl.addWidget(self.dot)
        fl.addWidget(self.name, 1)
        fl.addWidget(self.sc_lbl)
        fl.addWidget(self.btn)

        self.setToolTip(
            f"Pad {self.cfg.index + 1}  •  Shortcut: Ctrl+{self.cfg.index + 1}")

        vl.addWidget(self.preview, 1)
        vl.addWidget(footer)
        self._restyle()

    def _default_footer_name(self) -> str:
        if self.cfg.index == MEDIA_PAD and self.cfg.stype == SourceType.EMPTY:
            base = "Media (Image/Video)"
        elif self.cfg.index == CAMERA_PIP_PAD:
            return self.cfg.label or "Camera PIP"
        elif self.cfg.index == QUAD_PAD:
            base = "Quad Project"
        elif self.cfg.index == WEBCAM_PAD_VIDEO and self.cfg.stype == SourceType.EMPTY:
            return "Virtual Webcam"
        else:
            base = self.cfg.display_name
        if self.cfg.index not in (CAMERA_PIP_PAD, WEBCAM_PAD_VIDEO):
            if self.cfg.target_screen == -1:
                return f"[ALL] {base}"
            if self.cfg.target_screen is not None:
                return f"[D{self.cfg.target_screen + 1}] {base}"
        return base

    def _placeholder(self):
        from PyQt5.QtCore import QRect
        ph_h = PAD_H - 28   # 157 px
        pm = QPixmap(PAD_W, ph_h)
        pm.fill(QColor(C_KEY_BG))
        p = QPainter(pm)

        if self.cfg.index == MEDIA_PAD:
            p.setPen(QColor(C_MEDIA))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 18, QFont.Bold))
            p.drawText(QRect(0, 14, PAD_W, 34), Qt.AlignCenter, "🖼  ▶")
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 12, QFont.Bold))
            p.drawText(QRect(0, 56, PAD_W, 24), Qt.AlignCenter, "IMAGE /")
            p.drawText(QRect(0, 80, PAD_W, 24), Qt.AlignCenter, "VIDEO")
            p.setPen(QColor(C_DIM_K))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 8))
            p.drawText(QRect(4, 122, PAD_W - 8, 20), Qt.AlignCenter,
                       "click or ⚙ to select")

        elif self.cfg.index == CAMERA_PIP_PAD:
            p.setPen(QColor(C_CAMERA))
            p.setBrush(QColor(C_CAMERA + "28"))
            # Outer screen + lower-right PIP box icon
            p.drawRoundedRect((PAD_W - 64) // 2, 16, 64, 42, 4, 4)
            p.setBrush(QColor(C_CAMERA))
            p.drawRoundedRect((PAD_W - 64) // 2 + 36, 16 + 22, 24, 16, 2, 2)
            p.setBrush(Qt.NoBrush)
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 12, QFont.Bold))
            p.drawText(QRect(0, 68, PAD_W, 24), Qt.AlignCenter, "CAMERA PIP")
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 8, QFont.Bold))
            p.drawText(QRect(0, 92, PAD_W, 18), Qt.AlignCenter, "LOWER RIGHT")
            p.setPen(QColor(C_DIM_K))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 8))
            p.drawText(QRect(4, 124, PAD_W - 8, 20), Qt.AlignCenter,
                       "click ON/OFF • ⚙ setup")

        elif self.cfg.index == QUAD_PAD:
            # 2×2 grid icon
            p.setPen(QColor(C_QUAD))
            p.setBrush(QColor(C_QUAD + "33"))
            cell = 18
            gap  = 4
            gw   = cell * 2 + gap
            sx   = (PAD_W - gw) // 2
            sy   = 18
            for r in range(2):
                for c in range(2):
                    p.drawRect(sx + c * (cell + gap), sy + r * (cell + gap), cell, cell)
            p.setBrush(Qt.NoBrush)
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 13, QFont.Bold))
            p.drawText(QRect(0, 72, PAD_W, 26), Qt.AlignCenter, "QUAD")
            p.drawText(QRect(0, 96, PAD_W, 22), Qt.AlignCenter, "PROJECT")
            p.setPen(QColor(C_DIM_K))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 8))
            p.drawText(QRect(4, 130, PAD_W - 8, 20), Qt.AlignCenter,
                       "click to project Pads 1–4")

        elif self.cfg.index == WEBCAM_PAD_VIDEO:
            p.setPen(QColor(C_WEBCAM))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 18, QFont.Bold))
            p.drawText(QRect(0, 12, PAD_W, 36), Qt.AlignCenter, "▶  🖥")
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 13, QFont.Bold))
            p.drawText(QRect(0, 60, PAD_W, 26), Qt.AlignCenter, "WEBCAM")
            p.drawText(QRect(0, 86, PAD_W, 26), Qt.AlignCenter, "OUTPUT")
            p.setPen(QColor(C_DIM_K))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 8))
            p.drawText(QRect(4, 125, PAD_W - 8, 22), Qt.AlignCenter,
                       "video or screen / window")

        else:
            p.setPen(QColor(C_DIM_K))
            p.setFont(QFont("Segoe UI,Inter,sans-serif", 10))
            p.drawText(pm.rect(), Qt.AlignCenter,
                       f"Pad {self.cfg.index + 1}\n⚙  to configure\nCtrl+{self.cfg.index + 1}")

        p.end()
        self.preview.setPixmap(pm)

    def set_frame(self, px: QPixmap):
        sz = self.preview.size()
        if sz.width() < 10 or sz.height() < 10:
            sz = QSize(PAD_W, PAD_H - 28)
        scaled = px.scaled(sz, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        self.preview.setPixmap(scaled)

    def set_state(self, projected: bool = False, selected: bool = False,
                  webcam: bool = False):
        self._projected   = projected
        self._selected    = selected
        self._webcam_live = webcam
        self._restyle()
        if webcam and self.cfg.index == CAMERA_PIP_PAD:
            dot_color = C_CAMERA
        elif webcam:
            dot_color = C_WEBCAM
        elif projected:
            dot_color = C_QUAD if self.cfg.index == QUAD_PAD else (
                C_MEDIA if self.cfg.index == MEDIA_PAD else C_ACTIVE)
        elif selected:
            dot_color = "#FFFFFF"
        elif self.cfg.stype != SourceType.EMPTY:
            dot_color = "#8E8E93"
        else:
            dot_color = C_DIM_K
        self.dot.setStyleSheet(
            f"color:{dot_color};background:transparent;font-size:7px;")

    def update_cfg(self, cfg: PadConfig):
        self.cfg = cfg
        self.name.setText(self._default_footer_name())
        if cfg.stype == SourceType.EMPTY:
            self._placeholder()
        self._restyle()

    def _restyle(self):
        is_media  = self.cfg.index == MEDIA_PAD
        is_camera = self.cfg.index == CAMERA_PIP_PAD
        is_quad   = self.cfg.index == QUAD_PAD
        is_webcam = self.cfg.index == WEBCAM_PAD_VIDEO
        if self._webcam_live and is_camera:
            border = f"2px solid {C_CAMERA}"
        elif self._webcam_live:
            border = f"2px solid {C_WEBCAM}"
        elif self._projected:
            border = (f"2px solid {C_MEDIA}" if is_media else
                      f"2px solid {C_QUAD}" if is_quad else f"2px solid {C_ACTIVE}")
        elif self._selected:
            border = "2px solid #FFFFFF"
        elif self.cfg.stype != SourceType.EMPTY:
            border = f"1px solid {C_MEDIA}66" if is_media else f"1px solid {C_ACTIVE}55"
        elif is_media:
            border = f"1px solid {C_MEDIA}44"
        elif is_camera:
            border = f"1px solid {C_CAMERA}44"
        elif is_quad:
            border = f"1px solid {C_QUAD}44"
        elif is_webcam:
            border = f"1px solid {C_WEBCAM}44"
        else:
            border = f"1px solid {C_BORDER}"

        hover_border = (C_MEDIA if is_media else
                        C_CAMERA if is_camera else
                        C_QUAD if is_quad else
                        C_WEBCAM if is_webcam else "#FFFFFF")

        self.setStyleSheet(f"""
QFrame#Pad{{
  background:{C_KEY_BG};
  border:{border};
  border-radius:8px;
}}
QFrame#Pad:hover{{
  background:#222222;
  border-color:{hover_border};
}}
QWidget#Footer{{
  background:{C_KEY_FT};
  border-top:1px solid #2A2A2A;
  border-bottom-left-radius:8px;
  border-bottom-right-radius:8px;
}}
QLabel#Name{{
  color:{C_TEXT_K};
  font-size:11px;
  background:transparent;
}}
QToolButton#Gear{{
  background:transparent;
  border:none;
  color:{C_DIM_K};
  font-size:12px;
}}
QToolButton#Gear:hover{{color:{C_TEXT_K}}}
QLabel#ShortcutLbl{{
  color:#3A3A3C;
  font-size:9px;
  background:transparent;
}}
""")

    def mousePressEvent(self, e):
        if e.button() == Qt.LeftButton:
            self.clicked.emit(self.cfg.index)
        super().mousePressEvent(e)

    def contextMenuEvent(self, e):
        m = QMenu(self)
        m.setStyleSheet(
            f"QMenu{{background:{C_KEY_BG};border:1px solid #2E2E2E;"
            f"color:{C_TEXT_K};border-radius:6px;padding:4px}}"
            f"QMenu::item{{padding:6px 20px;border-radius:3px}}"
            f"QMenu::item:selected{{background:#2D2D2D}}"
        )
        is_media  = self.cfg.index == MEDIA_PAD
        is_camera = self.cfg.index == CAMERA_PIP_PAD
        is_quad   = self.cfg.index == QUAD_PAD
        is_webcam = self.cfg.index == WEBCAM_PAD_VIDEO
        if is_camera:
            label = "CAM   Turn Camera PIP Off" if self._webcam_live else "CAM   Turn Camera PIP On"
            a1 = m.addAction(label)
            a1.triggered.connect(lambda: self.clicked.emit(self.cfg.index))
            m.addSeparator()
            a2 = m.addAction("CONF  Camera & PIP Settings...")
            a2.triggered.connect(lambda: self.configure.emit(self.cfg.index))
        elif is_quad:
            a1 = m.addAction("GRID  Quad Project (Pads 1–4)")
            a1.triggered.connect(lambda: self.clicked.emit(self.cfg.index))
            self._add_target_submenu(m)
        elif is_webcam:
            label = "CAM  Start Webcam Output"
            a1 = m.addAction(label)
            a1.triggered.connect(lambda: self.clicked.emit(self.cfg.index))
            m.addSeparator()
            a2 = m.addAction("CONF  Configure Source...")
            a2.triggered.connect(lambda: self.configure.emit(self.cfg.index))
        elif is_media:
            a1 = m.addAction("PLAY  Project Media")
            a1.setEnabled(self.cfg.stype != SourceType.EMPTY)
            a1.triggered.connect(lambda: self.clicked.emit(self.cfg.index))
            m.addSeparator()
            a2 = m.addAction("CONF  Select Image / Video...")
            a2.triggered.connect(lambda: self.configure.emit(self.cfg.index))
            self._add_target_submenu(m)
            a3 = m.addAction("CLR   Clear Pad")
            a3.setEnabled(self.cfg.stype != SourceType.EMPTY)
            a3.triggered.connect(self._clear)
        else:
            a1 = m.addAction("PLAY  Project This Pad")
            a1.setEnabled(self.cfg.stype != SourceType.EMPTY)
            a1.triggered.connect(lambda: self.clicked.emit(self.cfg.index))
            m.addSeparator()
            a2 = m.addAction("CONF  Configure Source...")
            a2.triggered.connect(lambda: self.configure.emit(self.cfg.index))
            self._add_target_submenu(m)
            a3 = m.addAction("CLR   Clear Pad")
            a3.setEnabled(self.cfg.stype != SourceType.EMPTY)
            a3.triggered.connect(self._clear)
        m.exec_(e.globalPos())

    def _add_target_submenu(self, menu: QMenu):
        sub = menu.addMenu("OUT   Output Monitor")
        ext = [s for s in self._screens if not s.primary]

        a_def = sub.addAction("Default (Global Output)")
        a_def.setCheckable(True)
        a_def.setChecked(self.cfg.target_screen is None)
        a_def.triggered.connect(
            lambda: self.target_changed.emit(self.cfg.index, None))

        if ext:
            sub.addSeparator()
            for s in ext:
                act = sub.addAction(
                    f"Display {s.index + 1}: {s.name} ({s.bounds[2]}×{s.bounds[3]})")
                act.setCheckable(True)
                act.setChecked(self.cfg.target_screen == s.index)
                act.triggered.connect(
                    lambda _checked=False, idx=s.index:
                        self.target_changed.emit(self.cfg.index, idx))
            if len(ext) > 1:
                sub.addSeparator()
                a_all = sub.addAction(f"All External ({len(ext)} monitors)")
                a_all.setCheckable(True)
                a_all.setChecked(self.cfg.target_screen == -1)
                a_all.triggered.connect(
                    lambda: self.target_changed.emit(self.cfg.index, -1))

    def _clear(self):
        self.cfg.stype = SourceType.EMPTY
        self.cfg.sid   = None
        self.cfg.sname = "Empty"
        self.cfg.label = ""
        self.cfg.target_screen = None
        self.update_cfg(self.cfg)

